pr.solution:
def insert_at(a, P, x):
    a = a + [0]
    N = len(a)
    for k in range(N-1, P, -1):
        a[k] = a[k-1]
    a[P] = x
    return a

def delete_at(a, P):
    a = a + []
    N = len(a)
    for k in range(P, N-1):
        a[k] = a[k+1]
    b = [0]*(N-1)
    for k in range(0, N-1):
        b[k] = a[k]
    return b

def move_front(a, P):
    a = a + []
    temp = a[P]
    for k in range(P, 0, -1):
        a[k] = a[k-1]
    a[0] = temp
    return a

