def second_max(a):
    if a[0] > a[1]:
        maximum = a[0]
        secondmax = a[1]
    else:
        maximum = a[1]
        secondmax = a[0]
    for i in range(2, len(a)):
        if a[i] > maximum:
            secondmax = maximum
            maximum = a[i]
        elif a[i] > secondmax:
            secondmax = a[i]
    return secondmax

def dive(score, coef):
    total = 0
    for i in range(0, len(score)):
        total = total + score[i]
    neg = [0]*len(score)
    for i in range(0, len(score)):
        neg[i] = -score[i]
    max1 = max(score)
    max2 = second_max(score)
    min1 = min(score)
    min2 = -second_max(neg)
    return (total - max1 - max2 - min1 - min2) * coef

